
<!-- LinkItAll Puzzle -->
<template>

  <div>
    <div v-for="(q, q_ind) in qanda" :id="'question_' + q_ind" class="link-it-all-question">
      {{ q[0] }}
      <template v-for="(a, a_ind) in q[1]">
        <input v-if="a >= 0" @input="(e) => onChainInput(e, 'c-' + a)" @compositionend="onCompositionend" class="answerbox" :placeholder="a + 1" maxlength="1" v-model="text[a]">
        <input v-else-if="a == -1" type="text" @input="(e) => onNonChainInput(e, 't-' + q_ind + '-' + a_ind)" @compositionend="onCompositionend" class="answerbox" maxlength="1" v-model="nonChainText[q_ind][a_ind]">
        <span v-else>{{ a }}</span>
      </template>
    </div>
  </div>
  <v-stage ref="stage" :config="configKonva">
     <v-layer ref="grid">
      <template v-for="grid in grids">
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 1.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 1.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 3.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 3.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 1.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 1.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 3.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 3.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 0.5)*gridSize], stroke: 'black', strokeWidth: 4, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 2.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 2.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 4.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'black', strokeWidth: 4, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 0.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 0.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'black', strokeWidth: 4, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 2.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 2.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'grey', strokeWidth: 1, lineCap: 'round'}"/>
        <v-line :config="{x:0, y:0, points: [(grid[0] + 4.5) * gridSize, (grid[1] + 0.5)*gridSize, (grid[0] + 4.5)*gridSize, (grid[1] + 4.5)*gridSize], stroke: 'black', strokeWidth: 4, lineCap: 'round'}"/>
        <v-text :config="{text: grid[2], x:(grid[0] + 0.5) * gridSize, y:(grid[1] + 0.5)*gridSize, fill:'lightgrey', align: 'center', verticalAlign: 'middle', fontSize: 18, height: gridSize, width: gridSize}"/>
      </template>

    </v-layer>
     <v-layer>
      <v-line v-for="line in bonds" :config="{x:0, y:0, points: [line[0] * gridSize + (line[4] ? radius : 0), line[1] * gridSize + (line[4] ? 0 : radius), line[2] * gridSize - (line[4] ? radius : 0), line[3] * gridSize - (line[4] ? 0 : radius)], stroke: 'forestgreen', dash: [3,3], strokeWidth: 8}" />
    </v-layer>
    <v-layer ref="layer">
      <v-group v-for="(protein, g) in proteins" :config="{draggable : true, id: 'group' + g, opacity: 0.7}" @dragmove="() => { handleDragMove(g)}" @dragend="() => { handleDragEnd(g)}">
        <template v-for="(circle, i) in protein.protein">
          <v-line v-if="i < protein.protein.length - 1" :config="{x:0, y:0, points: [circle.x, circle.y, protein.protein[i+1].x, protein.protein[i+1].y], stroke: chainColor, strokeWidth: 20, shadowBlur: 10, shadowColor: '#2991ff'}" />
        </template>
        <v-circle v-for="(circle, i) in protein.protein" :config="circle" />
        <v-text @click="() => handleClickCircle(g, i)" v-for="(circle, i) in protein.protein"
                 @mousemove="(e) => handleMouseMove(e, circle.number)"
                 @mouseout="(e) => handleMouseOut(e, circle.number)"
                 :config="{text: circle.text ? circle.text : circle.number,
                           fill: 'white',
                           x: circle.x - gridSize / 2, y: circle.y - gridSize / 2 + 1,
                           align: 'center',
                           verticalAlign: 'middle',
                           fontSize: 18,
                           height: gridSize,
                           width: gridSize}" />
      </v-group>
    </v-layer>
    <v-layer>
      <v-rect v-if="showToolTip" :config="toolTipRectangleConfig" />
      <v-text ref="toolTip" v-if="showToolTip" :config="toolTipConfig" />
    </v-layer>
  </v-stage>

</template>

<style>

.link-it-all-question {
  display: flex;
  flex-wrap: wrap;
  gap: 1px;
  margin-bottom: 5px;
}
.link-it-all-question input{
  width: 23px;
  height: 23px;
  line-height: 23px;
  font-size: 14px;
  text-align: center;
  border: 1px solid #ccc;
  border-radius: 0;
  outline: none;
}
.link-it-all-question input::placeholder{
  font-size: 10px;
}

</style>

